<script>
(function(){
  var inp=document.getElementById('tofkSearch'),
      cnt=document.getElementById('tofkCount'),
      emp=document.getElementById('tofkEmpty'),
      tables=[].slice.call(document.querySelectorAll('table.tofk-t'));
  if(!inp||!tables.length)return;
  var rows=[],total=0;
  tables.forEach(function(t){var rs=[].slice.call(t.tBodies[0].rows);rows.push({t:t,rs:rs});total+=rs.length;});
  function norm(s){return (s||'').toLowerCase().replace(/ё/g,'е').trim();}
  inp.addEventListener('input',function(){
    var q=norm(inp.value),n=0;
    rows.forEach(function(g){
      var vis=0;
      g.rs.forEach(function(tr){
        var ok=!q||norm(tr.getAttribute('data-s')).indexOf(q)>-1;
        tr.style.display=ok?'':'none'; if(ok){vis++;n++;}
      });
      var hide=(vis===0)&&!!q;
      g.t.style.display=hide?'none':'';
      var h=g.t.previousElementSibling;
      if(h&&h.tagName==='H3') h.style.display=hide?'none':'';
    });
    cnt.textContent=q?('Найдено: '+n+' из '+total):('Управлений в справочнике: '+total);
    emp.style.display=(n===0)?'block':'none';
  });
})();
</script>

